class Solution {
public:
    int similarPairs(vector<string>& words) {
        vector<string> sig;
        for (auto& w : words) {
            set<char> s(w.begin(), w.end());
            sig.push_back(string(s.begin(), s.end()));
        }
        int ans = 0;
        for (int i = 0; i < (int)words.size(); i++)
            for (int j = i + 1; j < (int)words.size(); j++)
                if (sig[i] == sig[j]) ans++;
        return ans;
    }
};

