class Solution {
public:
    int similarPairs(vector<string>& words) {
        unordered_map<int, int> cnt;
        int ans = 0;
        for (auto& w : words) {
            int m = 0;
            for (char c : w) m |= 1 << (c - 'a');
            ans += cnt[m]++;
        }
        return ans;
    }
};

