class Solution {
    public int similarPairs(String[] words) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int ans = 0;
        for (String w : words) {
            int m = 0;
            for (char c : w.toCharArray()) m |= 1 << (c - 'a');
            ans += cnt.getOrDefault(m, 0);
            cnt.merge(m, 1, Integer::sum);
        }
        return ans;
    }
}

